 $('#gameSide').innerHTML=`<div class="compact-role"><span>${r.symbol}</span><b>${r.name}</b></div><button id="useSkill" class="skillbtn" ${!can?'disabled':''}>${!skillsOn?'技能关闭':g.done?'本局结束':role===2?'护盾已就绪':g.used?'技能已使用':g.picking?'取消选牌':r.skill}</button>${g.picking?`<div class="card-picker">${(poker?mine.cards:g.hand).map((c,i)=>`<button data-pick="${i}">替换 ${shortCard(c)}</button>`).join('')}</div>`:''}<details class="rail-details"><summary>技能说明</summary><div class="rail-popover">${skillsOn?r.desc[mode]:'经典规则桌 · 角色技能关闭。'}</div></details><details class="rail-details history-details"><summary>牌局记录</summary><div class="rail-popover log"><ul>${g.logs.slice(-20).map(s=>`<li>${s}</li>`).join('')}</ul></div></details><button id="aiInfo" class="ai-info">对手说明</button>`;
 $('#useSkill').onclick=skill;if($('#aiInfo'))$('#aiInfo').onclick=showAI;document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>replaceCard(+b.dataset.pick));document.querySelectorAll('[data-bj]').forEach(b=>b.onclick=()=>blackjackAct(b.dataset.bj));document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>humanPoker(b.dataset.act));
