 if($('#raiseRange')){$('#raiseRange').oninput=e=>{raiseTo=+e.target.value;$('#raiseInput').value=raiseTo};$('#raiseInput').oninput=e=>{raiseTo=+e.target.value;$('#raiseRange').value=raiseTo};document.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{raiseTo=Math.min(l.max,Math.max(l.min,g.current+Math.round((g.pot+l.owe)*+b.dataset.size)));$('#raiseRange').value=raiseTo;$('#raiseInput').value=raiseTo});$('#raiseButton').onclick=()=>humanPoker('raise',Number($('#raiseInput').value))}let ul=$('.log ul');if(ul)ul.scrollTop=ul.scrollHeight;
