async function humanPoker(action,target){if(busy||game.done||game.turn!==0)return;const g=game,token=epoch;try{busy=true;thinkingSeat=-1;await performPoker(0,action,target,g,token);if(current(g,token))await runPoker(g,token)}catch(e){if(current(g,token)){busy=false;toast(e.message);renderHud()}}}
function exitGame(){if(roomUI){roomUI.exit();return}if(screen==='lobby')return;if(guandanUI){guandanUI.exit();return}if(bigtwoUI){bigtwoUI.exit();return}if(crapsUI){crapsUI.exit();return}if(game&&!game.done){if(!confirm('离开牌桌将放弃本局已投入的筹码。确定离开？'))return;if(mode==='poker'){bank=game.reserve+game.players[0].chips;save()}}renderLobby()}
function showAI(){document.querySelector('.rule-tabs').style.display='none';$('#rules h2').textContent='对手如何做决定？';$('#ruleContent').innerHTML=`<p>每桌随机分配九种竞技策略中的不同组合。对手结合位置、有效筹码、多人底池、公开行动与加注尺度估计范围，再计算价值下注、跟注和诈唬的收益。</p><p>常规决策进行 1,200 次范围抽样；转牌和河牌进行 1,800 次。每位对手只接收自己的底牌和公开行动，不读取你的暗牌或真实牌堆。</p><p>人物的眨眼、表情和动作是独立随机的舞台表现，不能用来判断其牌力。</p><p>这些是本游戏的近似竞技策略，尚无职业模型评分或 GTO 求解器认证；不冒用 Pluribus 等研究模型的成绩。经典规则桌关闭角色技能，更适合练习。</p>`;$('#rules').showModal()}
async function showRules(which=mode){if(which==='bigtwo')({BIGTWO_RULES}=await import('./bigtwo-ui.mjs'));if(which==='roulette')({ROULETTE_RULES}=await import('./roulette-ui.mjs'));if(which==='guandan')({GUANDAN_RULES}=await import('./guandan-ui.mjs'));if(which==='craps')({CRAPS_RULES}=await import('./craps-ui.mjs'));document.querySelector('.rule-tabs').style.display='flex';$('#rules h2').textContent='上桌前，了解一下。';$('#ruleContent').innerHTML=which==='roulette'?ROULETTE_RULES:which==='guandan'?GUANDAN_RULES:which==='bigtwo'?BIGTWO_RULES:which==='craps'?CRAPS_RULES:which==='poker'?'<ol><li>可选 4–10 人无限注德州扑克，盲注 10 / 20。每局最多带入 2,000 筹码，电脑筹码在连续牌局间保留，筹码不足时重新买入。</li><li>可以过牌、跟注、弃牌，输入任意合法的下注总额，或全下。首次下注至少一个大盲；后续加注至少增加上一笔完整下注或加注的额度。没有加注次数上限。</li><li>例如：当前下注 60，上一次完整加注为 40，则最少加注至 100。界面的金额表示你本轮累计投入的总额，而非额外投入。</li><li>短码全下可低于最小加注；不足完整加注时，不会自动重新开放已行动者的加注权。累积短码全下达到完整加注时重新开放。</li><li>无人跟注的多余筹码退回，主池和边池分别结算。最佳五张牌相同则分池，零头筹码由庄位左侧起分配。</li></ol><p>牌型：同花顺 ＞ 四条 ＞ 葫芦 ＞ 同花 ＞ 顺子 ＞ 三条 ＞ 两对 ＞ 一对 ＞ 高牌。A2345 为最小顺子。</p><p>可在大厅关闭角色技能，进入经典规则桌。下注边界参考 <a href="https://www.pokertda.com/view-poker-tda-rules/" target="_blank" rel="noopener">Poker TDA 规则</a>。</p>':'<ol><li>J、Q、K 为 10 点，A 自动计 1 或 11 点。超过 21 点即爆牌。</li><li>要牌增加一张，停牌后庄家行动。两张手牌时可加倍下注，仅补一张牌后自动停牌。</li><li>庄家不足 17 点必须补牌，包含软 17 在内的 17 点及以上停牌。</li><li>天然 21 点为初始两张牌 A + 10 点牌，获胜赔付 3:2；普通获胜 1:1，平局退回下注。</li></ol><p>经典 21 点使用六副牌；初始同点数牌可分牌，最多四手，每手追加等额下注。分 A 后各补一张即停牌，分牌后的 21 点按普通获胜赔 1:1。可输入任意不超过可用筹码的正整数下注，不设额外桌面上限。不设投降和保险。</p>';if(SKILLS[which])$('#ruleContent').insertAdjacentHTML('beforeend','<h3>角色技能 · 每人每局一次</h3><ul>'+SKILLS[which].map((s,i)=>'<li><b>'+roles[i].name+' · '+s.name+'</b>：'+s.text+'</li>').join('')+'</ul><p>技能发动全桌可见，透视内容仅发动者可见。德州 1 BB = 20 筹码；技能费用进入底池，护盾及赏金由系统发放。</p>');document.querySelectorAll('[data-rule]').forEach(b=>b.classList.toggle('selected',b.dataset.rule===which));if(!$('#rules').open)$('#rules').showModal()}
$('#rulesNav').onclick=()=>showRules();$('#closeRules').onclick=()=>$('#rules').close();$('#rules').onclick=e=>{if(e.target===$('#rules')){let r=$('#rules').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#rules').close()}};document.querySelectorAll('[data-rule]').forEach(b=>b.onclick=()=>showRules(b.dataset.rule));$('#lobbyNav').onclick=exitGame;$('.brand').onclick=e=>{e.preventDefault();exitGame()};$('#sound').onclick=()=>{soundOn=!soundOn;$('#sound').innerHTML='♪ <span>音效'+(soundOn?'开':'关')+'</span>';$('#sound').setAttribute('aria-label',soundOn?'关闭音效':'开启音效');beep()};window.addEventListener('beforeunload',e=>{if((guandanUI&&!guandanUI.game.done)||(bigtwoUI?.game&&!bigtwoUI.game.done)||(game&&!game.done)||crapsUI?.engine.escrow||crapsUI?.engine.rolling){e.preventDefault();e.returnValue=''}});

function openRooms(invite=null){roomDirectory?.destroy();roomUI?.destroy();roomUI=new Rooms($('#app'),{mode,capacity:mode==='poker'?seatCount:4,role:window.clubPlayer?.role??role,skillsOn,onExit:async()=>{skillsOn=false;history.replaceState(null,'','/');await club.refreshOnce();role=window.clubPlayer.role;renderLobby()},toast,beep,reduced,invite,value:bigtwoValue})}
const club=new ClubUI({onReady:()=>{role=window.clubPlayer.role;renderLobby();const invite=new URLSearchParams(window.location.search).get('room');if(/^[a-f0-9]{32}$/.test(invite??''))openRooms(invite)},onBank:n=>{bank=n;wallet()},onBlocked:()=>{roomUI?.destroy();roomDirectory?.destroy();table?.destroy();document.body.classList.remove('in-game');$('#app').textContent='此设备暂未获准进入，请联系管理员。'}});

installButtonFeedback(beep);
